def update_signature_args(sig: inspect.Signature, arg_types: Dict[str, type], has_self: bool, existing_annotation_strategy: ExistingAnnotationStrategy = ExistingAnnotationStrategy.REPLICATE) -> inspect.Signature:
    params = []
    for i, (name, param) in enumerate(sig.parameters.items()):
        if has_self and i == 0:
            params.append(param.replace(annotation=inspect.Parameter.empty))
            continue
        if name not in arg_types:
            params.append(param)
            continue
        typ = arg_types[name]
        if existing_annotation_strategy == ExistingAnnotationStrategy.REPLICATE:
            if param.annotation is not inspect.Parameter.empty:
                params.append(param)
            elif typ is None:
                params.append(param)
            else:
                params.append(param.replace(annotation=typ))
        elif existing_annotation_strategy == ExistingAnnotationStrategy.IGNORE:
            if typ is None:
                params.append(param.replace(annotation=inspect.Parameter.empty))
            else:
                params.append(param.replace(annotation=typ))
        elif existing_annotation_strategy == ExistingAnnotationStrategy.OMIT:
            if param.annotation is not inspect.Parameter.empty:
                params.append(param.replace(annotation=inspect.Parameter.empty))
            elif typ is None:
                params.append(param)
            else:
                params.append(param.replace(annotation=typ))
    return sig.replace(parameters=params)

def render_parameter(param: inspect.Parameter) -> str:
    result = param.name
    if param.annotation is not inspect.Parameter.empty:
        anno = param.annotation
        if _is_optional(anno):
            rendered_anno = render_annotation(anno)
        elif param.default is None:
            rendered_anno = "Optional[" + render_annotation(anno) + "]"
        else:
            rendered_anno = render_annotation(anno)
        result += ": " + rendered_anno
    if param.default is not inspect.Parameter.empty:
        result += " = ..."
    return result

def render_signature(sig: inspect.Signature, max_line_len: Optional[int] = None, prefix: str = '') -> str:
    params = [render_parameter(p) for p in sig.parameters.values()]
    if sig.return_annotation is not inspect.Signature.empty:
        return_anno = " -> " + render_annotation(sig.return_annotation)
    else:
        return_anno = ""
    single_line = "(" + ", ".join(params) + ")" + return_anno
    if max_line_len is None or len(single_line) <= max_line_len:
        return single_line
    inner_prefix = prefix + "    "
    lines = ["("]
    for i, param in enumerate(params):
        comma = "," if i < len(params) - 1 else ""
        lines.append(inner_prefix + param + comma)
    lines.append(prefix + ")" + return_anno)
    return "\n".join(lines)

def generic_rewrite(self, typ: Any) -> str:
    if hasattr(typ, "__supertype__"):
        rendered = str(typ.__name__)
    elif is_forward_ref(typ):
        rendered = repr(typ.__forward_arg__)
    elif typ is NoneType:
        rendered = "None"
    elif is_generic(typ):
        rendered = repr(typ)
    elif isinstance(typ, type):
        if typ.__module__ in ("builtins",):
            rendered = typ.__qualname__
        else:
            rendered = typ.__module__ + "." + typ.__qualname__
    elif isinstance(typ, str):
        rendered = typ
    else:
        rendered = repr(typ)
    return rendered

def render(self, prefix: str = '') -> str:
    s = prefix
    if self.is_async:
        s += "async "
    s += "def " + self.name
    s += render_signature(self.signature, 120 - len(s), prefix) + ": ..."
    for module in self.strip_modules:
        s = s.replace(module + ".", "")
    if self.kind == FunctionKind.CLASS:
        s = prefix + "@classmethod\n" + s
    elif self.kind == FunctionKind.STATIC:
        s = prefix + "@staticmethod\n" + s
    elif self.kind == FunctionKind.PROPERTY:
        s = prefix + "@property\n" + s
    elif self.kind == FunctionKind.DJANGO_CACHED_PROPERTY:
        s = prefix + "@cached_property\n" + s
    return s
